UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications are open for 2026. <br/><strong>Online Application: </strong>This course is not available for online application. Please contact the team on the details below for further information on how to apply. <br/><strong>Apprenticeships/Traineeships: </strong>This course can be undertaken as a traineeship. Visit <a href="https://www.cdu.edu.au/tafe/apprenticeships-traineeships">TAFE Apprenticeships and Traineeships</a> for more information.</p><p>This qualification describes the skills and knowledge for general job roles in agriculture including livestock production, cropping or in the case of mixed farming workplaces, both cropping and livestock. Job roles vary across different industry sectors and may include:</p><ul><li>Farm or station hand</li><li>Farm or station worker</li><li>Livestock transport driver</li></ul><p>Individuals with this qualification perform tasks under broad supervision involving a broad range of skills that are applied in a wide variety of contexts, which will involve discretion and judgement in selecting and operating equipment, coordinating resources and applying contingency measures during work.</p><p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p><p>Possible occupations relevant to this qualification include:</p><ul><li>Farm or station hand</li><li>Farm or station worker</li><li>Livestock transport driver</li></ul><p><strong>Recognition of Prior Learning (RPL)</strong><br/><br/> RPL is the acknowledgement of a person''s skills and knowledge acquired through previous training, work or life experience, which may be used to grant status or credit in a subject regardless of how and where they were attained, including overseas.This can include skills from:</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals.</p><p>To gain entry into AHC30122 Certificate III in Agriculture, candidates require:</p><ul><li>To be physically fit, active, and able to function effectively in a tropical environment, as this is a physically demanding course.</li><li>Have a work contract with an approved employer to undertake a traineeship.</li></ul><p><strong>Resource Requirements</strong><br/>Students are issued with learning materials and handouts relevant for the units. Students are required to provide some of their own protective clothing for working outdoors including hats, sunglasses, appropriate footwear, long trousers, and long-sleeved shirts.</p><p>I wanted to turn my regular job into my dream job, and the Charles Darwin University course offered exactly what I needed: practical skills.</p><p> CDU student </p><p>CDU graduates have the best career and employment prospects. International students have ranked CDU 1st in Australia for learning and living experience</p><p> CDU student </p><p>I wanted to turn my regular job into my dream job, and the Charles Darwin University course offered exactly what I needed: practical skills.</p><p> CDU student </p><p>CDU graduates have the best career and employment prospects. International students have ranked CDU 1st in Australia for learning and living experience</p><p> CDU student </p>',
    apply_form = 'https://www.cdu.edu.au/study/course/ahc30122-certificate-iii-agriculture-ahc30122',
    updated_at = NOW()
WHERE cricos_course_code = '107364E';
UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications are open for 2026. <br/><strong>Online Application: </strong>This course is available for online application. <br/><strong>Apprenticeships/Traineeships: </strong>This course can be undertaken as a traineeship. Visit <a href="https://www.cdu.edu.au/tafe/apprenticeships-traineeships">TAFE Apprenticeships and Traineeships</a> for more information.</p><p>This qualification describes the skills and knowledge for general vocational job roles in the amenity horticulture industry.</p><p>This qualification is not intended to be used as a substitute for AHC Training Package trade qualifications.<br/>Individuals with this qualification perform tasks under broad supervision involving a broad range of skills that are applied in a wide variety of contexts, which will involve discretion and judgement in selecting and operating equipment, coordinating resources and applying contingency measures during work.<br/>Work must comply with work health and safety and environmental regulations and legislation that apply to the workplace.</p><p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p><p>Possible occupations relevant to this qualification include:</p><ul><li>gardener</li><li>landscape construction</li><li>landscape maintenance</li><li>horticulturist </li><li>nursery production </li><li>production horticulturist at a trade level </li><li>retail nursery </li></ul><p><strong>Recognition of Prior Learning (RPL)</strong><br/><br/> RPL is the acknowledgement of a person''s skills and knowledge acquired through previous training, work or life experience, which may be used to grant status or credit in a subject regardless of how and where they were attained, including overseas.This can include skills from:</p><ul><li>Previous study excluding courses at another VET/TAFE institution, but including courses at school or college, through adult education classes or training programs at work;</li><li>Work experience (including both work that is paid and unpaid); and/or</li><li>Life experience (for example leisure pursuits or voluntary work).</li></ul>',
    course_duration_per_week = 26,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals.</p><p>AHC30722 Certificate III in Horticulture is available for direct entry; however, it is recommended that candidates:</p><ul><li>Have successfully completed AHC20422 Certificate II in Horticulture or related qualification; <strong>or</strong></li><li>Have at least 1 year previous/current employment within the Horticulture industry; <strong>or </strong></li><li>Be a trainee with an existing work contract</li></ul><p><strong>Required Resources</strong><br/>Students will have 24/7 access to assessments and learning resources on CDU''s online learning platform Learnline. Before using Learnline however, students will need to ensure that their computer has the correct <a href="https://www.cdu.edu.au/current-students/services/learnline">setup</a>.</p><p>Students are issued with learning materials and handouts relevant to each unit.</p><p>Students are required to provide some of their own protective clothing for working outdoors, i.e. hat, closed-in-shoes, sunglasses, long trousers, and a long-sleeve shirt.</p><p>I learned everything I know about native plants from CDU. Before that, I only knew about European veggie gardens. Now I''m using what I learned at CDU at work.</p><p> CDU student </p><p>CDU graduates have the best career and employment prospects. International students have ranked CDU 1st in Australia for learning and living experience</p><p> CDU student </p><p>I learned everything I know about native plants from CDU. Before that, I only knew about European veggie gardens. Now I''m using what I learned at CDU at work.</p><p> CDU student </p>',
    apply_form = 'https://www.cdu.edu.au/study/course/ahc30722-certificate-iii-horticulture-ahc30722',
    updated_at = NOW()
WHERE cricos_course_code = '107364E';
