UPDATE courses SET
    course_description = '<p>The Bachelor of Accounting prepares you with professional skills to become an accountant or work in a range of roles that rely on accounting knowledge.</p><p>The course develops your communication, presentation and problem-solving skills. You''ll learn about financial accounting, management accounting, auditing, taxation, business law, corporate law, and finance.</p><p>You can also choose to study business units to complement your personal interests and career options. Or, you may choose electives from other areas, including language studies, anthropology, history, social science, Indigenous studies, applied science and engineering.</p><p>Completing a Bachelor of Accounting can lead to a wide range of career opportunities in small, medium and large organisations. As a graduate, you may become a financial accountant, management accountant, financial auditor, tax auditor/preparer, financial/business analyst, or work in a large multinational company or a Big Four accounting firm. Or, you could run your own businesses, work in a small local accounting firm, or work in other areas of business management.</p><p>As a graduate you''ll be eligible to apply for membership of CPA Australia, Chartered Accountants Australia and New Zealand (CAANZ), and Chartered Institute of Management Accountants (CIMA) UK.</p><p><strong>Pathways for VET to Higher Education</strong><br/>Credit transfer arrangements are available to students commencing a bachelor degree at Charles Darwin University with completed Certificate IV, Diploma, Advanced Diploma or Associate Degree qualifications in the same field or discipline, subject to meeting criteria. Students who hold completed qualifications should refer to the additional information provided about Advanced Standing and Credit Transfer and Pathways using the links below:</p><ul><li><a href="http://www.cdu.edu.au/current-students/credit-transfer-pathways">Credit Transfer and Pathways</a></li><li><a href="http://www.cdu.edu.au/student-central/advanced-standing">Advanced Standing</a></li></ul><p><br/><strong>Pathways for Higher Education to Higher Education</strong></p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 93624,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
