UPDATE courses SET
    course_description = '<p>The Bachelor of Computer Science will prepare you to be part of a continually evolving and diverse field, developing new applications and systems to improve the modern world. You will develop skills and knowledge in the technical principles and applications of computer science as well as strengthen your problem solving, decision making and communication skills making you a confident and competent candidate for a role in the IT industry.</p><p>Graduating from this course may lead to career opportunities as a computer scientist within the government sector, private companies and non-government organisations in areas such as web design and development, games developer, networking and application development, analyst, consultant, UX specialist, programmer, SEO specialist, database administrator, or business analyst.</p><p>The Bachelor of Computer Science is accredited by Australia Computer Society at the level of professional practice in ICT and therefore recognised internationally under the Seoul Accord.</p><p><strong>Pathways for VET to Higher Education</strong><br/>Credit transfer arrangements are available to students commencing a bachelor degree at Charles Darwin University with completed Certificate IV, Diploma, Advanced Diploma or Associate Degree qualifications in the same field or discipline, subject to meeting criteria. Students who hold completed qualifications should refer to the additional information provided about Advanced Standing and Credit Transfer and Pathways using the links below:</p><ul><li><a href="http://www.cdu.edu.au/current-students/credit-transfer-pathways">Credit Transfer and Pathways</a></li><li><a href="http://www.cdu.edu.au/student-central/advanced-standing">Advanced Standing</a></li></ul><p><br/><strong>Pathways for Higher Education to Higher Education</strong></p><p>For information about credit transfer available to students with complete or incomplete study at this or other Institutions refer to <a href="http://www.cdu.edu.au/current-students/credit-transfer-pathways">Pathways for Higher Education to Higher Education</a></p><p>For further information on credit transfer and how to apply visit <a href="http://ask.cdu.edu.au/app/answers/list/kw/credit%20transfer/p/0">ASK CDU</a></p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 104568,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
