UPDATE courses SET
    course_description = '<p>The Bachelor of Information Technology will prepare you to be responsible for more than just systems or software; you will be developing creative and innovative technologies for the modern world.</p><p>Throughout your studies, you will develop knowledge and skills in areas such as web design and development, networking, application development and systems.</p><p>You will also be encouraged to be an open-minded problem solver, a creative thinker as well as an engaging communicator, which will help progress your career in the IT industry.</p><p>Study opportunities are also provided to assist students to undertake sought-after industry modules, including Cisco and Microsoft certificates.</p><p>Graduating from this course may lead to career opportunities as an information technology specialist in government, private companies and non-government organisations (NGO) as a web designer and developer, networking and application developer, system analyst, consultant, programmer, SEO specialist, database administrator and project manager.</p><p>Graduates are eligible for membership of the Australian Computer Society (ACS) at the Professional Level. Students must select specialist units such that at least one of the three groups of specialist units are included.</p><p><strong>Pathways for VET to Higher Education</strong><br/>Credit transfer arrangements are available to students commencing a bachelor degree at Charles Darwin University with completed Certificate IV, Diploma, Advanced Diploma or Associate Degree qualifications in the same field or discipline, subject to meeting criteria. Students who hold completed qualifications should refer to the additional information provided about Advanced Standing and Credit Transfer and Pathways using the links below:</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 104568,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
