UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications are open for 2026.<br/><strong>Online Application: </strong>This course is available for online application. <br/><strong>Apprenticeships/Traineeships: </strong>This course can be undertaken as a traineeship. Visit <a href="https://www.cdu.edu.au/tafe/apprenticeships-traineeships">TAFE Apprenticeships and Traineeships</a> for more information. </p><p>This qualification reflects the role of individuals in a variety of Business Services job roles. These individuals may have frontline management accountabilities.</p><p>Individuals in these roles carry out moderately complex tasks in a specialist field of expertise that requires business operations skills. They may possess substantial experience in a range of settings, but seek to further develop their skills across a wide range of business functions.</p><p>This course can be undertaken as a traineeship. Visit <a href="https://www.cdu.edu.au/tafe/apprenticeships-traineeships">TAFE Apprenticeships and Traineeships</a> for more information.</p><p>Possible occupations relevant to this qualification include:</p><ul><li>Administrator</li><li>Business Development Manager</li><li>Corporate Services Manager</li><li>Executive Officer</li><li>Program Consultant</li><li>Program Coordinator</li></ul><p><strong>Recognition of Prior Learning (RPL)</strong><br/><br/> RPL is the acknowledgement of a person''s skills and knowledge acquired through previous training, work or life experience, which may be used to grant status or credit in a subject regardless of how and where they were attained, including overseas.This can include skills from:</p><ul><li>Previous study excluding courses at another VET/TAFE institution, but including courses at school or college, through adult education classes or training programs at work;</li><li>Work experience (including both work that is paid and unpaid); and/or</li><li>Life experience (for example leisure pursuits or voluntary work).</li></ul>',
    course_duration_per_week = 52,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>Students are required to undertake a Language, Literacy, Numeracy and Digital Literacy (LLND) assessment to establish support requirements for this qualification.</p><p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals.</p><p>To gain entry into BSB50120 Diploma of Business, candidates require: </p><ul><li>BSB40215 Certificate IV in Business and/or equivalent vocational competency, and/or</li><li>A minimum of two years'' workplace experience in an administrative or clerical role.</li></ul><p><strong>Required Resources</strong></p><p>Students will have 24/7 access to assessments and learning resources on CDU''s online learning platform Learnline. Before you can use Learnline however, you''ll need to ensure that your computer has the correct <a href="https://www.cdu.edu.au/current-students/services/learnline">setup</a>.</p><p>The people-first approach to flexibility and supportive learning environment at CDU meant I could find a balance with study, work and family life.</p><p> CDU student </p><p>I genuinely believe Darwin is the land of opportunities if you leverage your strengths, abilities and skills.</p><p> CDU student </p><p>The people-first approach to flexibility and supportive learning environment at CDU meant I could find a balance with study, work and family life.</p><p> CDU student </p>',
    apply_form = 'https://www.cdu.edu.au/study/course/bsb50120-diploma-business-bsb50120',
    updated_at = NOW()
WHERE cricos_course_code = '0100739';
