UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications for 2026 will open in November 2025. <br/><strong>Online Application: </strong>To be confirmed. Please contact the team on the details below for further information on how to apply. <br/><strong>Apprenticeships/Traineeships: </strong>Currently not available as either an apprenticeship or traineeship.</p><p>This qualification reflects the role of individuals who apply a broad range of competencies in various work contexts in the music industry.</p><p>They use some discretion, judgement and theoretical knowledge, and may undertake routine activities and provide support to a team or work group.</p><p>They may work in music performance, sound production, music creation and composition, music business.</p><p>Possible occupations relevant to this qualification include:</p><ul><li>Assistant sound technician </li><li>Assistant music manager</li><li>Musician</li><li>Sound assistant</li><li>Road crew</li></ul><p><strong>Recognition of Prior Learning (RPL)</strong><br/><br/> RPL is the acknowledgement of a person''s skills and knowledge acquired through previous training, work or life experience, which may be used to grant status or credit in a subject regardless of how and where they were attained, including overseas.This can include skills from:</p><ul><li>Previous study excluding courses at another VET/TAFE institution, but including courses at school or college, through adult education classes or training programs at work;</li><li>Work experience (including both work that is paid and unpaid); and/or</li><li>Life experience (for example leisure pursuits or voluntary work).</li></ul>',
    course_duration_per_week = 52,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals.</p><p><strong>Required Resources</strong><br/>Students will have 24/7 access to assessments and learning resources on CDU''s online learning platform Learnline. Before using Learnline however, students will need to ensure that their computer has the correct <a href="https://www.cdu.edu.au/current-students/services/learnline">setup</a>.</p><p>Computer and internet access is required to source information and complete assessments. It is recommended students bring a laptop with them to class so they can access online resources</p><p>Students are issued with learning materials and handouts for each unit.</p><p>Having lecturers who were practising artists themselves gave me a greater understanding of the art world and their guidance was invaluable.</p><p> CDU student </p><p>Through the experiences I’ve had of exhibiting my art in open spaces, I’ve learned about the joys and challenges of engaging diverse publics in art. It has encouraged me to do more in art and in engaging with others.</p><p> CDU student </p><p>Having lecturers who were practising artists themselves gave me a greater understanding of the art world and their guidance was invaluable.</p><p> CDU student </p><p>Through the experiences I’ve had of exhibiting my art in open spaces, I’ve learned about the joys and challenges of engaging diverse publics in art. It has encouraged me to do more in art and in engaging with others.</p><p> CDU student </p>',
    apply_form = 'https://www.cdu.edu.au/study/course/cua30920-certificate-iii-music-cua30920',
