UPDATE courses SET
    course_description = '<p>The Diploma of Creative Arts introduces students to ways of making, performing, and presenting creative work. The course is designed to help each student find and develop their unique creative voice with the support of experienced teachers who are creative professionals. Students collaborate with each other and connect with the Australian creative sector in the context of discovering their creative potential.</p><p>The Diploma of Creative Arts offers an introduction to contemporary creative arts, leading to further study or entry-level careers in the creative sector. The course provides foundational knowledge and learning experiences to develop students'' playfulness and confidence in creative thinking and practices, their awareness of cultural, health, and safety issues relating to work in arts sectors, as well as critical thinking, research skills, and creative collaboration.</p><p>Students choose to specialise in an arts discipline through studio practice units in one of the following:</p><ul><li>Music</li><li>Screen Media Arts, or </li><li>Visual Arts.</li></ul><p>The Diploma of Creative Arts is delivered from an Australian perspective through in-person and online delivery, ensuring maximum learning flexibility. Optional field trips in the Northern Territory are embedded to connect students to the creative sector in the north of Australia.</p><p>The course is delivered full-time over one year or part-time over two years. The Diploma provides a pathway into the Bachelor of Creative Arts for those who want to continue their studies, or it is a stand-alone program for those seeking an undergraduate qualification in a short duration.</p><p>The Diploma of Creative Arts introduces students to contemporary creative arts from an Australian perspective, with the option to specialise in one discipline area.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>Admission requirements are met by one of the following:</p><ul><li>Successful completion of the Northern Territory Certificate of Education and Training (or equivalent) and the awarding of an Australian Tertiary Admissions Rank (ATAR) of at least <strong>60</strong>*.</li><li>Successful completion of a national qualification at Certificate III level or higher.</li><li>Successful completion of at least 0.5 year of full-time study (or equivalent) of a higher education degree/diploma.</li><li>Overseas secondary or tertiary qualifications considered equivalent to the above Australian qualifications.</li><li>Attainment of a <a href="https://www.cdu.edu.au/launchpad/future-study/four-pathways-get-university">STAT</a> Multiple Choice score of 140.</li><li>Successful completion of the <a href="https://www.cdu.edu.au/education/tep">Tertiary Enabling Program</a>, the Preparation for Tertiary Success courses, or other recognised tertiary preparation course.</li><li>Submission of an acceptable <a href="https://satac.edu.au/personal-competencies-statement">personal competencies statement</a> and/or employment experience.</li><li>Australian Defence Force (ADF) members with service of 1 year or more at the following ranks (or higher) meet the academic entry requirement for this course: <ul><li>Navy: Seaman, Able Seaman, Leading Seaman</li><li>Air Force: Aircraftmen/Aircraftwoman, Leading Aircraftman/Aircraftwoman, Corporal</li><li>Army: Private, Lance Corporal, Corporal</li></ul></li><li><a href="https://www.cdu.edu.au/study/essentials/study-pathways/school-leaver-admission-pathways">Current School Leaver Pathways</a>: <ul><li>Best of 3 Year 12 subject grades</li><li>School recommendation program</li></ul></li></ul><ul><li>Navy: Seaman, Able Seaman, Leading Seaman</li><li>Air Force: Aircraftmen/Aircraftwoman, Leading Aircraftman/Aircraftwoman, Corporal</li><li>Army: Private, Lance Corporal, Corporal</li></ul><ul><li>Best of 3 Year 12 subject grades</li><li>School recommendation program</li></ul><p>* After any applicable <a href="https://www.cdu.edu.au/study/essentials/study-pathways/pathways-study#apply-with-your-australian-tertiary-admission-ranking--atar-">adjustment factors</a> have been applied.</p><p><strong>DOMESTIC STUDENTS</strong></p><p>To gain entry into Charles Darwin University, all Higher Education applicants must satisfy the University''s English Language Proficiency Requirements for their chosen course of study. All applicants will be required to supply evidence of this at the time of application.</p><p>The minimum English language requirement for this course can be met by evidencing of one of the following: </p><p><br/><strong>^ Minimum Requirements for English Tests:</strong></p><p><br/>IELTS One Skill Retake is accepted, allowing candidates to retake a single skill within 60 days of sitting their initial test. One Skill Retake results are valid for two years from the date of the first test (not from the date of the Retake test) to the date of commencement at CDU. </p><p>CDU accepts combined results from two test sittings of IELTS Academic, PTE Academic, or TOEFL, taken within a six-month period, if:</p><ul><li>Both tests were under the same testing system; and</li><li>The overall score in both tests meets the overall minimum; and</li><li>The applicant achieved the section minimum for each section in at least one test. </li></ul>',
    apply_form = 'https://www.cdu.edu.au/study/course/diploma-creative-arts-ycart1',
    updated_at = NOW()
WHERE cricos_course_code = '116333D';
UPDATE courses SET
    course_description = '<p>The Diploma of Digital Enterprise is a flexible, one-year qualification that combines the strengths of business and information technology to prepare you for careers shaped by innovation and rapid digital change. You will develop a foundation in management, marketing, digital product development, and data-driven decision-making, while also gaining core IT capabilities in web development, systems, networking, and applications.</p><p>This unique mix enables you to understand how organisations operate, create value and compete in modern digital environments. Designed for flexibility, the degree lets you tailor your studies to your interests with a wide selection of business and IT units, and you can study online or on campus.</p><p>On completing this course, you will be eligible to transfer into the Bachelor of Digital Enterprise, or you may choose to specialise and move into the Bachelor of Business or Bachelor of Information Technology.</p><p>As a Diploma of Digital Enterprise graduate, you will have the foundation to pursue further study and the knowledge to take up an entry-level role at the intersection of business and technology. You will be prepared to contribute to digital transformation, manage innovative projects and support organisations as they adapt to emerging technologies.</p><p>For further information on credit transfer and how to apply visit <a href="http://ask.cdu.edu.au/app/answers/list/kw/credit%20transfer/p/0">ASK CDU</a></p><p>For further information on credit transfer and how to apply visit <a href="http://ask.cdu.edu.au/app/answers/list/kw/credit%20transfer/p/0">ASK CDU</a></p><p>Commonwealth Supported places are available in this course to students who meet one of the following residency requirements:<br/><br/> (a) be an Australian citizen, who will complete some of your course of study while resident in Australia; or<br/><br/> (b) a New Zealand citizen; or an Australian permanent visa holder; or an eligible former permanent humanitarian visa holder; who studies the entire course while living in Australia.<br/><br/> Further information about fees and charges can be found at <a href="http://www.cdu.edu.au/student-central/fees-payments/domestic-fees">Fees and Payments</a>.</p><p>The annual tuition fee for full time study in 2026 is AUD $31,208.00. This equates to $3,901.00 per 10 credit point unit (0.125 EFTSL).<br/>These fees are subject to increases annually, effective at the start of each calendar year.<br/><br/>You can find a list of <a href="https://www.cdu.edu.au/international/how-apply/international-fees-and-payments">International fees and payments</a> you can expect to pay as part of your studies in Australia. See <a href="https://www.cdu.edu.au/files/2025-08/2026-he-international-annual-tuition-fees.pdf">2026 Higher Education International Annual Tuition Fees</a>.<br/><br/>CDU offers a number of <a href="https://www.cdu.edu.au/international/how-apply/scholarships-and-finance-international-students">scholarships</a> to international students to assist with the cost of study. </p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 31208,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>Stage 2 Mathematical Methods or equivalent.</p><p>Admission requirements are met by one of the following:</p><ul><li>Successful completion of the Northern Territory Certificate of Education and Training (or equivalent) and the awarding of an Australian Tertiary Admissions Rank (ATAR) of at least <strong>60</strong>*.</li><li>Successful completion of a national qualification at Certificate III level or higher.</li><li>Successful completion of at least 0.5 year of full-time study (or equivalent) of a higher education degree/diploma.</li><li>Overseas secondary or tertiary qualifications considered equivalent to the above Australian qualifications.</li><li>Attainment of a <a href="https://www.cdu.edu.au/launchpad/future-study/four-pathways-get-university">STAT</a> Multiple Choice score of 140.</li><li>Successful completion of the <a href="https://www.cdu.edu.au/education/tep">Tertiary Enabling Program</a>, the Preparation for Tertiary Success courses, or other recognised tertiary preparation course.</li><li>Submission of an acceptable <a href="https://satac.edu.au/personal-competencies-statement">personal competencies statement</a> and/or employment experience.</li><li>Australian Defence Force (ADF) members with service of 1 year or more at the following ranks (or higher) meet the academic entry requirement for this course: <ul><li>Navy: Seaman, Able Seaman, Leading Seaman</li><li>Air Force: Aircraftmen/Aircraftwoman, Leading Aircraftman/Aircraftwoman, Corporal</li><li>Army: Private, Lance Corporal, Corporal</li></ul></li><li><a href="https://www.cdu.edu.au/study/essentials/study-pathways/school-leaver-admission-pathways">Current School Leaver Pathways</a>: <ul><li>Best of 3 Year 12 subject grades</li><li>School recommendation program</li></ul></li></ul><ul><li>Navy: Seaman, Able Seaman, Leading Seaman</li><li>Air Force: Aircraftmen/Aircraftwoman, Leading Aircraftman/Aircraftwoman, Corporal</li><li>Army: Private, Lance Corporal, Corporal</li></ul><ul><li>Best of 3 Year 12 subject grades</li><li>School recommendation program</li></ul><p>* After any applicable <a href="https://www.cdu.edu.au/study/essentials/study-pathways/pathways-study#apply-with-your-australian-tertiary-admission-ranking--atar-">adjustment factors</a> have been applied.</p><p>International applicants who have completed the CDU Foundation Studies Program and achieved a minimum mark of 65% in the Foundation English units A and B are eligible to apply.</p><p><strong>DOMESTIC STUDENTS</strong></p><p>To gain entry into Charles Darwin University, all Higher Education applicants must satisfy the University''s English Language Proficiency Requirements for their chosen course of study. All applicants will be required to supply evidence of this at the time of application.</p><p>The minimum English language requirement for this course can be met by evidencing of one of the following: </p><p><br/><strong>^ Minimum Requirements for English Tests:</strong></p><p><br/>IELTS One Skill Retake is accepted, allowing candidates to retake a single skill within 60 days of sitting their initial test. One Skill Retake results are valid for two years from the date of the first test (not from the date of the Retake test) to the date of commencement at CDU. </p>',
    apply_form = 'https://www.cdu.edu.au/study/course/diploma-digital-enterprise-ydige1',
    updated_at = NOW()
WHERE cricos_course_code = '0101377';
UPDATE courses SET
    course_description = '<p>The Diploma of Educational Studies is a flexible one-year qualification designed to support diverse career and study pathways in education. The course equips you with foundational knowledge and skills to work in a variety of educational settings, including school-age education support, out-of-school-hours care, and community-based learning environments.</p><p>This course also provides entry-level preparation for roles supporting learners with diverse needs, including in remote, regional, and First Nations contexts.</p><p>Graduates may pursue employment in educational and community settings across Australia, subject to state and territory requirements. Potential roles include:</p><ul><li>Aboriginal and/or Torres Strait Islander Education Worker</li><li>Language and Culture Teaching Assistant</li><li>Homeland Teaching Assistant</li><li>Education Assistant (including Special Needs and Inclusion Support)</li><li>Teacher Aide or Classroom Assistant</li><li>Support Worker in Out-of-School-Hours or Vacation Care Programs</li><li>Education Support Worker </li></ul><p>For further information on credit transfer and how to apply visit <a href="http://ask.cdu.edu.au/app/answers/list/kw/credit%20transfer/p/0">ASK CDU</a></p><p>For further information on credit transfer and how to apply visit <a href="http://ask.cdu.edu.au/app/answers/list/kw/credit%20transfer/p/0">ASK CDU</a></p><p>Commonwealth Supported places are available in this course to students who meet one of the following residency requirements:<br/><br/> (a) be an Australian citizen, who will complete some of your course of study while resident in Australia; or<br/><br/> (b) a New Zealand citizen; or an Australian permanent visa holder; or an eligible former permanent humanitarian visa holder; who studies the entire course while living in Australia.<br/><br/> Further information about fees and charges can be found at <a href="http://www.cdu.edu.au/student-central/fees-payments/domestic-fees">Fees and Payments</a>.</p><p>Educate and inspire the next generation with a teaching degree at CDU. You''ll gain the skills and knowledge to enter the classroom with confidence, equipped with a nationally-accredited degree to work anywhere in Australia.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>Admission requirements are met by one of the following:</p><ul><li>Successful completion of the Northern Territory Certificate of Education and Training (or equivalent) and the awarding of an Australian Tertiary Admissions Rank (ATAR) of at least <strong>60</strong>*.</li><li>Successful completion of a national qualification at Certificate III level or higher.</li><li>Successful completion of at least 0.5 year of full-time study (or equivalent) of a higher education degree/diploma.</li><li>Overseas secondary or tertiary qualifications considered equivalent to the above Australian qualifications.</li><li>Attainment of a <a href="https://www.cdu.edu.au/launchpad/future-study/four-pathways-get-university">STAT</a> Multiple Choice score of 140.</li><li>Successful completion of the <a href="https://www.cdu.edu.au/education/tep">Tertiary Enabling Program</a>, the Preparation for Tertiary Success courses, or other recognised tertiary preparation course.</li><li>Submission of an acceptable <a href="https://satac.edu.au/personal-competencies-statement">personal competencies statement</a> and/or employment experience.</li><li>Australian Defence Force (ADF) members with service of 1 year or more at the following ranks (or higher) meet the academic entry requirement for this course: <ul><li>Navy: Seaman, Able Seaman, Leading Seaman</li><li>Air Force: Aircraftmen/Aircraftwoman, Leading Aircraftman/Aircraftwoman, Corporal</li><li>Army: Private, Lance Corporal, Corporal</li></ul></li><li><a href="https://www.cdu.edu.au/study/essentials/study-pathways/school-leaver-admission-pathways">Current School Leaver Pathways</a>: <ul><li>Best of 3 Year 12 subject grades</li><li>School recommendation program</li></ul></li></ul><ul><li>Navy: Seaman, Able Seaman, Leading Seaman</li><li>Air Force: Aircraftmen/Aircraftwoman, Leading Aircraftman/Aircraftwoman, Corporal</li><li>Army: Private, Lance Corporal, Corporal</li></ul><ul><li>Best of 3 Year 12 subject grades</li><li>School recommendation program</li></ul><p>* After any applicable <a href="https://www.cdu.edu.au/study/essentials/study-pathways/pathways-study#apply-with-your-australian-tertiary-admission-ranking--atar-">adjustment factors</a> have been applied.</p><p><strong>DOMESTIC STUDENTS</strong></p><p>To gain entry into Charles Darwin University, all Higher Education applicants must satisfy the University''s English Language Proficiency Requirements for their chosen course of study. All applicants will be required to supply evidence of this at the time of application.</p><p>The minimum English language requirement for this course can be met by evidencing of one of the following: </p><p><br/><strong>^ Minimum Requirements for English Tests:</strong></p><p><br/>IELTS One Skill Retake is accepted, allowing candidates to retake a single skill within 60 days of sitting their initial test. One Skill Retake results are valid for two years from the date of the first test (not from the date of the Retake test) to the date of commencement at CDU. </p><p>CDU accepts combined results from two test sittings of IELTS Academic, PTE Academic, or TOEFL, taken within a six-month period, if:</p><ul><li>Both tests were under the same testing system; and</li><li>The overall score in both tests meets the overall minimum; and</li><li>The applicant achieved the section minimum for each section in at least one test. </li></ul>',
    apply_form = 'https://www.cdu.edu.au/study/course/diploma-educational-studies-yeds02',
    updated_at = NOW()
WHERE cricos_course_code = '0100739';
UPDATE courses SET
    course_description = '<p>The Diploma of Engineering is ideal if you are curious about studying engineering and would like to learn more, but are unsure about committing to a full undergraduate degree.</p><p>During your engineering studies, you will explore some of the general concepts, principles and practices of engineering, develop your technical skills and build upon your maths and science knowledge.</p><p>With the diploma, you qualify for entry-level engineering roles, or you can continue onto other engineering degree courses such as CDU''s Associate Degree in Engineering, Bachelor of Engineering Science, or Bachelor of Engineering Honours.</p><p>Graduating from the Diploma of Engineering may lead to entry-level engineering roles.</p><p>For further information on credit transfer and how to apply visit <a href="http://ask.cdu.edu.au/app/answers/list/kw/credit%20transfer/p/0">ASK CDU</a></p><p>For further information on credit transfer and how to apply visit <a href="http://ask.cdu.edu.au/app/answers/list/kw/credit%20transfer/p/0">ASK CDU</a></p><p>Commonwealth Supported places are available in this course to students who meet one of the following residency requirements:<br/><br/> (a) be an Australian citizen, who will complete some of your course of study while resident in Australia; or<br/><br/> (b) a New Zealand citizen; or an Australian permanent visa holder; or an eligible former permanent humanitarian visa holder; who studies the entire course while living in Australia.<br/><br/> Further information about fees and charges can be found at <a href="http://www.cdu.edu.au/student-central/fees-payments/domestic-fees">Fees and Payments</a>.</p><p>The annual tuition fee for full time study in 2026 is AUD $39,392.00. This equates to $4,924.00 per 10 credit point unit (0.125 EFTSL).<br/>These fees are subject to increases annually, effective at the start of each calendar year.<br/><br/>You can find a list of <a href="https://www.cdu.edu.au/international/how-apply/international-fees-and-payments">International fees and payments</a> you can expect to pay as part of your studies in Australia. See <a href="https://www.cdu.edu.au/files/2025-08/2026-he-international-annual-tuition-fees.pdf">2026 Higher Education International Annual Tuition Fees</a>.<br/><br/>CDU offers a number of <a href="https://www.cdu.edu.au/international/how-apply/scholarships-and-finance-international-students">scholarships</a> to international students to assist with the cost of study. </p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 39392,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>Admission requirements are met by one of the following:</p><ul><li>Successful completion of the Northern Territory Certificate of Education and Training (or equivalent) and the awarding of an Australian Tertiary Admissions Rank (ATAR) of at least <strong>60</strong>*.</li><li>Successful completion of a national qualification at Certificate III level or higher.</li><li>Successful completion of at least 0.5 year of full-time study (or equivalent) of a higher education degree/diploma.</li><li>Overseas secondary or tertiary qualifications considered equivalent to the above Australian qualifications.</li><li>Attainment of a <a href="https://www.cdu.edu.au/launchpad/future-study/four-pathways-get-university">STAT</a> Multiple Choice score of 140.</li><li>Successful completion of the <a href="https://www.cdu.edu.au/education/tep">Tertiary Enabling Program</a>, the Preparation for Tertiary Success courses, or other recognised tertiary preparation course.</li><li>Submission of an acceptable <a href="https://satac.edu.au/personal-competencies-statement">personal competencies statement</a> and/or employment experience.</li><li>Australian Defence Force (ADF) members with service of 1 year or more at the following ranks (or higher) meet the academic entry requirement for this course: <ul><li>Navy: Seaman, Able Seaman, Leading Seaman</li><li>Air Force: Aircraftmen/Aircraftwoman, Leading Aircraftman/Aircraftwoman, Corporal</li><li>Army: Private, Lance Corporal, Corporal</li></ul></li><li><a href="https://www.cdu.edu.au/study/essentials/study-pathways/school-leaver-admission-pathways">Current School Leaver Pathways</a>: <ul><li>Best of 3 Year 12 subject grades</li><li>School recommendation program</li></ul></li></ul><ul><li>Navy: Seaman, Able Seaman, Leading Seaman</li><li>Air Force: Aircraftmen/Aircraftwoman, Leading Aircraftman/Aircraftwoman, Corporal</li><li>Army: Private, Lance Corporal, Corporal</li></ul><ul><li>Best of 3 Year 12 subject grades</li><li>School recommendation program</li></ul><p>* After any applicable <a href="https://www.cdu.edu.au/study/essentials/study-pathways/pathways-study#apply-with-your-australian-tertiary-admission-ranking--atar-">adjustment factors</a> have been applied.</p><p>International applicants who have completed the CDU Foundation Studies Program and achieved a minimum mark of 65% in the Foundation English units A and B are eligible to apply.</p><p>There are several domains of inherent requirements for the engineering suite of courses. All the Inherent requirement domains and statements can be found from the link below.</p><p><a href="https://www.cdu.edu.au/inherent-requirements/engineering">Inherent requirement for Engineering</a></p><p><strong>DOMESTIC STUDENTS</strong></p><p>To gain entry into Charles Darwin University, all Higher Education applicants must satisfy the University''s English Language Proficiency Requirements for their chosen course of study. All applicants will be required to supply evidence of this at the time of application.</p><p>The minimum English language requirement for this course can be met by evidencing of one of the following: </p><p><br/><strong>^ Minimum Requirements for English Tests:</strong></p>',
    apply_form = 'https://www.cdu.edu.au/study/course/diploma-engineering-yeng01',
    updated_at = NOW()
WHERE cricos_course_code = '060196G';
