UPDATE courses SET
    course_description = '<p>The Master of Applied Linguistics at CDU is a postgraduate degree that prepares you for analysis, evaluation, and application of linguistic understandings to language, its use, and its role in various contexts. You will build theoretical foundations in applied linguistics for developing knowledge and awareness in the field that targets developments in practice and research. The focus of the program is on contextualised evaluation of language, which can be applied to theoretical analysis or contribute to the continuing professional development of linguists, language teachers, TESOL practitioners, and education policy makers. You will explore content incorporating aspects that can be applied to local, regional and global contexts, and offer directed engagement with First Nations, Australian, Asian and global content and perspectives.</p><p>Study opportunities exist on-campus or online, in full-time or part-time study modes. You may personalise your course by completing a capstone research project in an area of interest that is complemented by additional coursework electives. Areas of focus across the course include Indigenous languages, linguistic analysis and documentation, language teaching and testing, and sociolinguistics. All areas are represented in coursework components, and in pursuing a capstone research project, you will have access to an expert research supervisor, who will guide you in the research journey</p><p>Graduating from this course may lead to career opportunities in fields concerned with applied linguistics, language education, policy making, and professional domains where language, its use and role are a priority. </p><p>Graduates may also be provided with pathways for further study at the PhD level through research preparation.</p><p><br/><strong>Pathways for Higher Education to Higher Education</strong></p><p>For information about credit transfer available to students with complete or incomplete study at this or other Institutions refer to <a href="http://www.cdu.edu.au/current-students/credit-transfer-pathways">Pathways for Higher Education to Higher Education</a></p><p>For further information on credit transfer and how to apply visit <a href="http://ask.cdu.edu.au/app/answers/list/kw/credit%20transfer/p/0">ASK CDU</a></p><p>For further information on credit transfer and how to apply visit <a href="http://ask.cdu.edu.au/app/answers/list/kw/credit%20transfer/p/0">ASK CDU</a></p>',
    course_duration_per_week = 78,
    offshore_tuition_fee = 75344,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>Successful completion of a recognised bachelor degree, graduate certificate, graduate diploma, master''s degree, or equivalent international qualification.</p><p>Applicants who have completed the CDU Accelerated International Masters Qualifying Program (ZAMQP2, ZAMQP1) are eligible for entry.</p><p><strong>DOMESTIC STUDENTS</strong></p><p>To gain entry into Charles Darwin University, all Higher Education applicants must satisfy the University''s English Language Proficiency Requirements for their chosen course of study. All applicants will be required to supply evidence of this at the time of application.</p><p>The minimum English language requirement for this course can be met by evidencing of one of the following: </p><p><br/><strong>^ Minimum Requirements for English Tests:</strong></p><p><br/>IELTS One Skill Retake is accepted, allowing candidates to retake a single skill within 60 days of sitting their initial test. One Skill Retake results are valid for two years from the date of the first test (not from the date of the Retake test) to the date of commencement at CDU. </p><p>CDU accepts combined results from two test sittings of IELTS Academic, PTE Academic, or TOEFL, taken within a six-month period, if:</p><ul><li>Both tests were under the same testing system; and</li><li>The overall score in both tests meets the overall minimum; and</li><li>The applicant achieved the section minimum for each section in at least one test. </li></ul><p><strong>Recognised English-speaking countries:</strong></p><p>For further details on the English requirements for CDU courses, please refer to the <a href="https://policies.cdu.edu.au/view-current.php?id=178">CDU English Language Proficiency Policy</a>.<br/></p><p><strong>INTERNATIONAL STUDENTS</strong></p>',
    apply_form = 'https://www.cdu.edu.au/study/course/master-applied-linguistics-sappl1',
    updated_at = NOW()
WHERE cricos_course_code = '116332E';
UPDATE courses SET
    course_description = '<p>The Master of Applied Spatial Science has been designed to provide upskilling in geographic information systems (GIS) and remote sensing skills to a diverse array of vocations. The course is aimed at those with little or no previous spatial science experience and can be undertaken by students with a bachelor''s degree in any field. The course will guide you through the fundamentals and develop more advanced geospatial skills. The outcome will be that you will be able to solve real-world problems across a diverse range of fields and vocations, such as environmental science, health, agriculture, mining, disaster and emergency management, and even tourism and business.</p><p>Spatial Science skills are in high demand in Australia and overseas, and spatial science graduates can work across a broad range of roles, including Spatial Analysts, Spatial Ecologists, GIS Analysts, Remote Sensing Specialists, Geospatial Intelligence Analysts, Geospatial Data Analysts, Geomarketing Officers, Cartographers, Surveyor assistants, Surveyor Technicians, or Drone Pilots/Photogrammetrists. Students in this course actively participate in professional work placements and field work. </p><p>Through this course, you will gain important transferable employability skills, including collaboration, preparing a resume and addressing selection criteria, clear scientific writing, report writing, and preparing and delivering oral presentations.</p><p>The Graduate Certificate of Spatial Science is nested within the Master''s degree course as an entry and exit pathway. </p><p>Master of Applied Spatial Science graduates are in high demand in Australia and internationally to work in governments, industry, and research, taking on a wide range of roles, including:</p><ul><li>Remote Sensing Specialist</li><li>GIS Analyst/Technician</li><li>Earth Observation Analyst/Scientist</li><li>Geospatial Intelligence Analyst</li><li>GIS Manager</li><li>Geospatial Data Scientist</li><li>Environmental Consultant</li></ul><p>"Australia is grappling with a significant shortage of geospatial professionals" (Geospatial Council of Australia, 2025) as the demand for geospatial experts across Australian states and territories is growing exponentially. The average salary for a graduate geospatial analyst in Australia is $86,500 per annum (Glassdoor Australia, 2025). Graduates do not require certification from a professional body to practice their profession.</p><p>This course offers a pathway for professionals from any background to upskill or reskill for career opportunities in geospatial science and remote sensing, including roles with industry, government research institutes, or private consultancies. There are opportunities for graduates to apply for and enter the NTG Graduate Development Program upon completing the course.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 74448,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>Successful completion of a recognised bachelor''s degree or equivalent international qualification. <br/></p><p>Applicants who have completed the CDU International Masters Qualifying Program (ZMQP01) or the Accelerated International Masters Qualifying Program (ZAMQP2, ZAMQP1) are eligible for entry.</p><p><strong>DOMESTIC STUDENTS</strong></p><p>To gain entry into Charles Darwin University, all Higher Education applicants must satisfy the University''s English Language Proficiency Requirements for their chosen course of study. All applicants will be required to supply evidence of this at the time of application.</p><p>The minimum English language requirement for this course can be met by evidencing of one of the following: </p><p><br/><strong>^ Minimum Requirements for English Tests:</strong></p><p><br/>IELTS One Skill Retake is accepted, allowing candidates to retake a single skill within 60 days of sitting their initial test. One Skill Retake results are valid for two years from the date of the first test (not from the date of the Retake test) to the date of commencement at CDU. </p><p>CDU accepts combined results from two test sittings of IELTS Academic, PTE Academic, or TOEFL, taken within a six-month period, if:</p><ul><li>Both tests were under the same testing system; and</li><li>The overall score in both tests meets the overall minimum; and</li><li>The applicant achieved the section minimum for each section in at least one test. </li></ul><p><strong>Recognised English-speaking countries:</strong></p><p>For further details on the English requirements for CDU courses, please refer to the <a href="https://policies.cdu.edu.au/view-current.php?id=178">CDU English Language Proficiency Policy</a>.<br/></p><p><strong>INTERNATIONAL STUDENTS</strong></p>',
    apply_form = 'https://www.cdu.edu.au/study/course/master-applied-spatial-science-sspsc1',
    updated_at = NOW()
WHERE cricos_course_code = '107551B';
UPDATE courses SET
    course_description = '<p>The Master of Architecture will provide a well-rounded architectural education to prepare students for contemporary professional practice leading to registration as an Architect. Students who have completed the Bachelor of Architectural Design are eligible for entry into the course. The course curriculum builds on the knowledge and skills from the undergraduate Bachelor of Architectural Design with a focus on designing for extreme climates. With a particular focus on sustainable built environments in the diverse climatic regions of the Northern Territory and the Asia-Pacific, students will learn how to create innovative design solutions that respond to complex architectural problems.</p><p>Students refine their 3D modeling skills to realise architectural designs, prepare architectural documentation and detailing that contribute to the quality of the built environment and human well-being. The course focuses on principles and practices of design thinking from the perspectives of Indigenous knowledge, environmental sustainability, economic prosperity, justice, and fairness. Students also learn how architectural firms operate, their professional standards, and the contracting, procurement, and project delivery processes.</p><p>This course is focused on developing professional and research competencies in the creation of works of architecture and includes options to complete a major research project or practice placement.</p><p>Available for enrolment in internal on campus mode and external mode, the course does require all students to have laptop or PC access with appropriate specs and high-speed broadband for the completion of project work.</p><p>Graduating from the Master of Architecture can lead to professional opportunties in the architecture, design, construction and project management fields; and is the primary pathway leading to registration as an architect.</p><p>The process for the Initial Accreditation of the Master of Architecture course has commenced between the Architects Accreditation Council of Australia (AACA), the Northern Territory Architects Board (NTAB), and Charles Darwin University (CDU). This process is being undertaken in accordance with the Architecture Program Accreditation Procedure and is subject to the outcome of the Accreditation Review Panel. The Initial Accreditation Review is scheduled to occur during Semester 2, 2027. </p><p>Once Accreditation has been successfully achieved, graduates who have completed a minimum of 3,300 hours (approximately two years, at least one year of which must be postgraduate) of practical experience under the supervision of an Architect, will be eligible to undertake the Architectural Practice Examination (APE). A successful pass of the APE will enable Graduates to be eligible for Professional Registration with any Architects Board in Australia. </p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 75344,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>Successful completion of a recognised bachelor degree in architecture or equivalent international qualification, and either:</p><ul><li>A GPA of at least-4.5-from the eligible bachelor degree in Architecture; or</li><li>At least-six months post-degree employment experience in professional architectural fields within Australia. Applicants using this pathway must upload a CV detailing their experience to their SATAC application.</li></ul><p><strong>DOMESTIC STUDENTS</strong></p><p>To gain entry into Charles Darwin University, all Higher Education applicants must satisfy the University''s English Language Proficiency Requirements for their chosen course of study. All applicants will be required to supply evidence of this at the time of application.</p><p>The minimum English language requirement for this course can be met by evidencing of one of the following: </p><p><br/><strong>^ Minimum Requirements for English Tests:</strong></p><p><br/>IELTS One Skill Retake is accepted, allowing candidates to retake a single skill within 60 days of sitting their initial test. One Skill Retake results are valid for two years from the date of the first test (not from the date of the Retake test) to the date of commencement at CDU. </p><p>CDU accepts combined results from two test sittings of IELTS Academic, PTE Academic, or TOEFL, taken within a six-month period, if:</p><ul><li>Both tests were under the same testing system; and</li><li>The overall score in both tests meets the overall minimum; and</li><li>The applicant achieved the section minimum for each section in at least one test. </li></ul><p><strong>Recognised English-speaking countries:</strong></p><p>For further details on the English requirements for CDU courses, please refer to the <a href="https://policies.cdu.edu.au/view-current.php?id=178">CDU English Language Proficiency Policy</a>.<br/></p><p><strong>INTERNATIONAL STUDENTS</strong></p>',
    apply_form = 'https://www.cdu.edu.au/study/course/master-architecture-sarch1',
    updated_at = NOW()
WHERE cricos_course_code = '118201M';
UPDATE courses SET
    course_description = '<p>CDU''s Master of Arts (Coursework) is a flexible, postgraduate unit-based course that offers students opportunities to develop competencies in a range of fields, enhance career progression, update skills, and pursue their interests in arts and social sciences. It also offers the usual preparation for students seeking a pathway into Higher Degree by Research programs, such as a Master by Research or a Doctor of Philosophy. </p><p>You''ll choose to specialise in one of the following areas:</p><ul><li>Social Sciences</li><li>Indigenous Knowledges and Engagement</li><li>Indigenous Languages and Contemporary Social Issues</li><li>Indigenous Research Practice</li><li>Creative Arts</li></ul><p>In addition to these specialisations, you can select a Research Option if you''d like to develop research skills and gain research experience alongside your coursework studies. The Research Option may equip students for entry into future HDR programs, depending on the entry requirements of the institution.</p><p>Whether you want to consolidate your expertise or forge a new career path, this degree will equip you with the analytical and critical thinking skills you need to succeed.</p><p>At CDU, you''ll explore unique perspectives on the contemporary issues facing Indigenous Australia, Northern Australia and South-East Asia. Our lecturers are leaders in their fields and are ready to guide and mentor you.</p><p>In a world where opinions are rife, but facts and considered thought may not be, your ability to critically evaluate ideas, concepts and information will set you apart.</p><p>A Master of Arts is a great way to deepen and strengthen your knowledge and skills across a wide range of professional careers from the creative industry to Indigenous policy. The course offers the opportunity to credit the work you are doing on existing projects towards your study.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 75344,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>Successful completion of a recognised bachelor degree, graduate certificate, graduate diploma, master''s degree, or equivalent international qualification.</p><p>International Pathway<br/> Applicants who have completed the CDU International Masters Qualifying Program (ZMQP01) or the Accelerated International Masters Qualifying Program (ZAMQP1) are eligible for entry.</p><p><strong>DOMESTIC STUDENTS</strong></p><p>To gain entry into Charles Darwin University, all Higher Education applicants must satisfy the University''s English Language Proficiency Requirements for their chosen course of study. All applicants will be required to supply evidence of this at the time of application.</p><p>The minimum English language requirement for this course can be met by evidencing of one of the following: </p><p><br/><strong>^ Minimum Requirements for English Tests:</strong></p><p><br/>IELTS One Skill Retake is accepted, allowing candidates to retake a single skill within 60 days of sitting their initial test. One Skill Retake results are valid for two years from the date of the first test (not from the date of the Retake test) to the date of commencement at CDU. </p><p>CDU accepts combined results from two test sittings of IELTS Academic, PTE Academic, or TOEFL, taken within a six-month period, if:</p><ul><li>Both tests were under the same testing system; and</li><li>The overall score in both tests meets the overall minimum; and</li><li>The applicant achieved the section minimum for each section in at least one test. </li></ul><p><strong>Recognised English-speaking countries:</strong></p><p>For further details on the English requirements for CDU courses, please refer to the <a href="https://policies.cdu.edu.au/view-current.php?id=178">CDU English Language Proficiency Policy</a>.<br/></p><p><strong>INTERNATIONAL STUDENTS</strong></p>',
    apply_form = 'https://www.cdu.edu.au/study/course/master-arts-coursework-sarts2',
    updated_at = NOW()
