UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications for 2026 are now closed. The next available intake will commence in Semester 1 2027 with applications opening in November 2026.<br/><strong>Online Application: </strong>This course is available for online application. <br/><strong>Apprenticeships/Traineeships: </strong>This course can be undertaken as an apprenticeship. Visit <a href="https://www.cdu.edu.au/tafe/apprenticeships-traineeships">TAFE Apprenticeships and Traineeships</a> for more information. (example)</p><p>This qualification reflects the role of hairdressers who use a range of well-developed sales, consultation and technical skills and knowledge to provide a broad range of hairdressing services to clients. They use discretion and judgement to provide client services and take responsibility for the outcomes of their own work.</p><p>This qualification provides a pathway to work as a hairdresser in any industry environment, usually a salon.</p><p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p><p><strong>Alice Springs</strong><br/>09/02/2026 to 25/11/2026</p><p><strong>Palmerston</strong><br/>02/02/2026 to 31/11/2026<br/>*Students must enrol in the course prior to the commencement date.<br/>*Apprentices will receive an individual call-up notification letter. <br/>*A course timetable/study plan will be provided on application for the course.</p><p><strong>Mainstream</strong><br/>Classes: Monday, Tuesday and Wednesday<br/>8:30am - 4:30pm<br/>Self-paced learning: Thursday<br/>8:30am - 4:30pm<br/>Training supplemented by (1) day per week placement in a commercial salon.</p><p><strong>Apprentice</strong><br/>Stage 1 Apprentice<br/>Wednesday<br/>8:30am to 4:30pm<br/>Stage 2 Apprentice<br/>Tuesday<br/>8:30am to 4:30pm<br/>Stage 3 Apprentice<br/>Monday<br/>8:30am to 4:30pm</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals.</p><p>To gain entry into SHB30416 Certificate III in Hairdressing as an Apprentice, candidates require:</p><ul><li>To be an Apprentice who has entered a Training Contract with their employer and the Australian Apprenticeship Support Network NT.</li></ul><p>Students can undertake this course as a non-apprentice at the Alice Springs campus; the full-time course program is designed for applicants over the age of 21.</p><p>The Training Salon is a simulated work environment and requires students to wear work clothing suited to the industry.</p><p><strong>Required Resources</strong><br/>Students will have 24/7 access to assessments and learning resources on CDU''s online learning platform Learnline. Before using Learnline however, students will need to ensure that their computer has the correct <a href="https://www.cdu.edu.au/current-students/services/learnline">setup</a>.</p><p>Students are required to purchase a Skin Deep book pack from the Hairdressing Reception, pricing will be provided at the information sessions.</p><p>All the lessons included theory and practical. We got to train with real clients in a busy environment and I got so much out of that.</p><p> CDU student </p><p>Hands-on practical lessons, experienced instructors, and all the resources that CDU provides will absolutely bring your skills and knowledge up to scratch–you won’t believe how much you’ll learn during the process.</p><p> CDU student </p><p>All the lessons included theory and practical. We got to train with real clients in a busy environment and I got so much out of that.</p>',
    apply_form = 'https://www.cdu.edu.au/study/course/shb30416-certificate-iii-hairdressing-shb30416',
    updated_at = NOW()
WHERE cricos_course_code = '107364E';
UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications for 2026 are now closed. The next available intake will commence in Semester 1 2027 with applications opening in November 2026.<br/><strong>Online Application: </strong>This course is available for online application. <br/><strong>Apprenticeships/Traineeships: </strong>This course can be undertaken as an apprenticeship. Visit <a href="https://www.cdu.edu.au/tafe/apprenticeships-traineeships">TAFE Apprenticeships and Traineeships</a> for more information. (example)</p><p>This qualification reflects the role of barbers who use a range of well-developed sales, consultation and technical skills and knowledge to provide a broad range of barbering services to clients. They use discretion and judgement to provide client services and take responsibility for the outcomes of their own work.</p><p>This qualification provides a pathway to work as a barber in any industry environment, usually a barber shop or salon.</p><p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p><p><strong>Alice Springs</strong><br/>09/02/2026 to 25/11/2026</p><p><strong>Palmerston</strong><br/>02/02/2026 to 30/11/2026<br/>*Apprentices will receive an individual call-up notification letter. <br/>*A course timetable/study plan will be provided on application for the course.</p><p><strong>Alice Springs</strong><br/><strong>Mainstream</strong><br/>Monday and Wednesday<br/>8:30am to 4:00pm<br/>This training is supplemented by 1 day per week work placement in a commercial salon</p><p><strong>Apprentice</strong><br/>1st year Apprentice<br/>Wednesday<br/>8:30am to 4:00pm<br/>2nd and 3rd year Apprentice<br/>Monday<br/>8:30am to 4:00pm</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 17654,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals.</p><p>To gain entry into SHB30516 Certificate III in Barbering as an Apprentice, candidates require:</p><ul><li>To be an Apprentice who has entered a Training Contract with their employer and Australian Apprenticeship Support Network NT.</li></ul><p>Students can undertake this course as non-apprentices at the Alice Springs campus; the full-time course program is designed for applicants over the age of 21.</p><p>The Training Salon is a simulated work environment and requires students to wear work clothing suited to the industry.</p><p><strong>Required Resources</strong><br/>Students will have 24/7 access to assessments and learning resources on CDU''s online learning platform Learnline. Before using Learnline however, students will need to ensure that their computer has the correct <a href="https://www.cdu.edu.au/current-students/services/learnline">setup</a>.</p><p>Computer and internet access is required to source information and complete assessments.</p><p>Students are required to purchase a Skin Deep book pack from the Hairdressing Reception, that will be tailored to the Full Time Barbering course. Approximate pricing will be provided at the information sessions.</p><p>All the lessons included theory and practical. We got to train with real clients in a busy environment and I got so much out of that.</p><p> CDU student </p><p>Hands-on practical lessons, experienced instructors, and all the resources that CDU provides will absolutely bring your skills and knowledge up to scratch–you won’t believe how much you’ll learn during the process.</p><p> CDU student </p>',
    apply_form = 'https://www.cdu.edu.au/study/course/shb30516-certificate-iii-barbering-shb30516',
    updated_at = NOW()
WHERE cricos_course_code = '107364E';
-- ⏭️ (no CRICOS): SHB50121 Diploma of Beauty Therapy | https://www.cdu.edu.au/study/course/shb50121-diploma-beauty-therapy-shb50121

UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications are open for 2026.<br/><strong>Online Application: </strong>This course is available for online application. <br/><strong>Apprenticeships/Traineeships: </strong>This course can be undertaken as a traineeship. Visit <a href="https://www.cdu.edu.au/tafe/apprenticeships-traineeships">TAFE Apprenticeships and Traineeships</a> for more information.</p><p>This qualification reflects the role of individuals who have the primary responsibility of engaging the <br/>customer, maintaining daily store operations and delivering on organisational expectations. They have sound knowledge of product and service offerings. These individuals possess a range of well-developed skills where discretion and judgement is required. They work with some independence under limited supervision. Some individuals working at this level are responsible for supervising other team members and monitoring day-to-day workplace operations.</p><p>The qualification provides a pathway to work in a diverse range of retail settings including specialty retailers, supermarkets, department stores and quick service restaurants. Individuals with this qualification can perform roles such as frontline sales assistant, customer service representative, shop assistant, retail supervisor, team leader and senior sales assistant.</p><p>Possible occupations relevant to this qualification include:</p><ul><li>frontline sales assistant </li><li>customer service representative </li><li>retail assistant</li><li>retail supervisor </li><li>team leader (retail)</li><li>cashier</li></ul><p><strong>Recognition of Prior Learning (RPL)</strong><br/><br/> RPL is the acknowledgement of a person''s skills and knowledge acquired through previous training, work or life experience, which may be used to grant status or credit in a subject regardless of how and where they were attained, including overseas.This can include skills from:</p><ul><li>Previous study excluding courses at another VET/TAFE institution, but including courses at school or college, through adult education classes or training programs at work;</li><li>Work experience (including both work that is paid and unpaid); and/or</li><li>Life experience (for example leisure pursuits or voluntary work).</li></ul><p>RPL is a form of assessment. It is used to determine whether a person has acquired, through formal or informal learning, the skills and experience consistent with the stated competency standards that comprise a qualification. RPL is <strong>not time referenced</strong>, so there are no parameters on how or when the skills are acquired. However, the skills that have been acquired through life experience etc., must be current and must match the elements and performance criteria contained in the individual unit.<br/><br/> Students seeking RPL need to indicate this on their enrolment form at the time of enrolment.<br/><br/> For further information please refer to the <a href="http://www.cdu.edu.au/course-docs/ApplicantsGuidetoRPLv1.6.pdf">Applicant''s Guide to the Recognition of Prior Learning</a> or contact Student Central on <strong>1800 061 963</strong> (free call) or email <a href="mailto:Student.Central@cdu.edu.au">Student.Central@cdu.edu.au</a>.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>A pre-enrolment process to establish suitability to undertake the course and to determine support requirements will be conducted, which will include a Language, Literacy, Numeracy and Digital Literacy (LLND) assessment.</p><p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals.</p><p>Students require a retail workplace where they can have a minimum of three (3) hours weekly practice to develop their skill base. This can be unpaid, such as a volunteer in a charity store. </p><p><strong>Required Resources</strong><br/>Students are provided with a Learner Guide and access to online modules.</p><p>Computer and internet access is required to source information and complete assessments.</p><p>The people-first approach to flexibility and supportive learning environment at CDU meant I could find a balance with study, work and family life.</p><p> CDU student </p><p>I genuinely believe Darwin is the land of opportunities if you leverage your strengths, abilities and skills.</p><p> CDU student </p><p>The people-first approach to flexibility and supportive learning environment at CDU meant I could find a balance with study, work and family life.</p><p> CDU student </p><p>I genuinely believe Darwin is the land of opportunities if you leverage your strengths, abilities and skills.</p>',
    apply_form = 'https://www.cdu.edu.au/study/course/sir30216-certificate-iii-retail-sir30216',
    updated_at = NOW()
WHERE cricos_course_code = '107364E';
UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications are open for 2026. <br/><strong>Online Application: </strong>This course is not available for online application. Please contact the team on the details below for further information on how to apply. <br/><strong>Apprenticeships/Traineeships: </strong>This course can be undertaken as an apprenticeship. Visit <a href="https://www.cdu.edu.au/tafe/apprenticeships-traineeships">TAFE Apprenticeships and Traineeships</a> for more information.</p><p>Add Course/Program/Qualification description here</p><p>Possible occupations relevant to this qualification include:</p><ul><li>Store Manager</li><li>Department Manager</li><li>Assistant Store Manager</li></ul><p><strong>Recognition of Prior Learning (RPL)</strong><br/><br/> RPL is the acknowledgement of a person''s skills and knowledge acquired through previous training, work or life experience, which may be used to grant status or credit in a subject regardless of how and where they were attained, including overseas.This can include skills from:</p><ul><li>Previous study excluding courses at another VET/TAFE institution, but including courses at school or college, through adult education classes or training programs at work;</li><li>Work experience (including both work that is paid and unpaid); and/or</li><li>Life experience (for example leisure pursuits or voluntary work).</li></ul><p>RPL is a form of assessment. It is used to determine whether a person has acquired, through formal or informal learning, the skills and experience consistent with the stated competency standards that comprise a qualification. RPL is <strong>not time referenced</strong>, so there are no parameters on how or when the skills are acquired. However, the skills that have been acquired through life experience etc., must be current and must match the elements and performance criteria contained in the individual unit.<br/><br/> Students seeking RPL need to indicate this on their enrolment form at the time of enrolment.<br/><br/> For further information please refer to the <a href="http://www.cdu.edu.au/course-docs/ApplicantsGuidetoRPLv1.6.pdf">Applicant''s Guide to the Recognition of Prior Learning</a> or contact Student Central on <strong>1800 061 963</strong> (free call) or email <a href="mailto:Student.Central@cdu.edu.au">Student.Central@cdu.edu.au</a>.</p><p><strong>Credit Transfer</strong><br/><br/> Charles Darwin University as a Registered Training Organisation recognises the Australian Qualifications Framework qualifications and Statement of Attainments issued by any other Australian Registered Training Organisation.<br/><br/> Students are encouraged to submit any requests for credit from previous studies at the time of enrolment, to ensure they are not enrolling in units they may not need to undertake.<br/><br/> In order to apply for exemption/credit transfer from units completed at another training organisation, you will need to complete an <a href="http://www.cdu.edu.au/files/2023-03/tafe110-application-for-credit-transfer.pdf">Application for Exemption Form</a> available from any campus, centre, or team, or a copy of the form can be obtained from the web.<br/><br/> Your completed Application for Exemption form together with attached documentary evidence (certified copy of Qualification/Statement of Attainment) to support your request for exemption/credit transfer should be submitted directly to the University either in person or by mail. Requests without documentary evidence will not be processed and will be returned to students. There are no fees attached to Credit Transfers.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>A pre - enrolment process to establish suitability to undertake the course and to determine support requirements will be conducted, which will include a Language, Literacy and Numeracy (LLN) assessment.</p><p>To gain entry into SIR40316 Certificate IV in Retail Management, candidates require:</p><ul><li>have achieved a Certificate III in Retail</li></ul><p><strong>OR</strong></p><ul><li>have relevant industry employment experience in a job role that has involved the application of skills and knowledge described in core units of competency from the SIR30216 Certificate III in Retail.</li></ul><p><strong>Required Resources</strong><br/>Students will have 24/7 access to assessments and learning resources on CDU''s online learning platform Learnline. Before using Learnline however, students will need to ensure that their computer has the correct <a href="https://www.cdu.edu.au/current-students/services/learnline">setup</a>.</p><p>The people-first approach to flexibility and supportive learning environment at CDU meant I could find a balance with study, work and family life.</p><p> CDU student </p><p>I genuinely believe Darwin is the land of opportunities if you leverage your strengths, abilities and skills.</p><p> CDU student </p><p>The people-first approach to flexibility and supportive learning environment at CDU meant I could find a balance with study, work and family life.</p><p> CDU student </p>',
    apply_form = 'https://www.cdu.edu.au/study/course/sir40316-certificate-iv-retail-management-sir40316',
    updated_at = NOW()
WHERE cricos_course_code = '109632G';
-- ⏭️ (no CRICOS): SIS20122 Certificate II in Sport and Recreation | https://www.cdu.edu.au/study/course/sis20122-certificate-ii-sport-recreation-sis20122

-- ⏭️ (no CRICOS): SIS30122 Certificate III in Sport, Aquatics and Recreation | https://www.cdu.edu.au/study/course/sis30122-certificate-iii-sport-aquatics-recreation-sis30122

UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications are open for 2026. <br/><strong>Online Application: </strong>This course is available for online application. <br/><strong>Apprenticeships/Traineeships: </strong>This course can be undertaken as a traineeship. Visit <a href="https://www.cdu.edu.au/tafe/apprenticeships-traineeships">TAFE Apprenticeships and Traineeships</a> for more information. (example)</p><p>This qualification reflects the role of group and gym fitness instructors. These fitness instructors may plan and deliver group exercise sessions and develop gym-based programs for individuals where the level of personalised instruction and ongoing client monitoring is limited.</p><p>They work in predictable environments under general supervision. When instructing groups or interacting with clients, they use discretion and judgment to solve routine issues within the parameters of clearly defined organisational policies and procedures.</p><p>The skills in this qualification must be applied in accordance with Commonwealth and State or Territory legislation, Australian standards and industry codes of practice.</p><p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p><p>Possible occupations relevant to this qualification include:</p><ul><li>Aqua instructor</li><li>Group fitness instructor</li><li>Gym instructor</li><li>Exercise instructor</li></ul><p><strong>Recognition of Prior Learning (RPL)</strong><br/><br/> RPL is the acknowledgement of a person''s skills and knowledge acquired through previous training, work or life experience, which may be used to grant status or credit in a subject regardless of how and where they were attained, including overseas.This can include skills from:</p>',
    course_duration_per_week = 26,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals.</p><p>To gain entry into SIS30321 Certificate III in Fitness, candidates require:</p><ul><li>To have access to a Fitness facility supervised by qualified trainers (paid or volunteer). </li><li>To hold or must be eligible for a Working with Children Check</li></ul><p><strong>Required Resources</strong><br/>Students will have 24/7 access to assessments and learning resources on CDU''s online learning platform Learnline. Before using Learnline however, students will need to ensure that their computer has the correct <a href="https://www.cdu.edu.au/current-students/services/learnline">setup</a>.</p><p>Students are required to purchase a uniform shirt to wear when undertaking practical placement and attending community events.</p><p>Additional costs to students include:</p><ul><li>Working with Children Clearance - Standard Fee (Employment) $87.00</li><li>Working with Children Clearance - Concession Fee (Volunteer) $8.00</li></ul><p>The people-first approach to flexibility and supportive learning environment at CDU meant I could find a balance with study, work and family life.</p><p> CDU student </p><p>Charles Darwin University is a platform that can serve as a bridge for your future. Australia is a land of opportunities and when you work hard you get to see the fruits of your labour.</p><p> CDU student </p><p>The people-first approach to flexibility and supportive learning environment at CDU meant I could find a balance with study, work and family life.</p>',
    apply_form = 'https://www.cdu.edu.au/study/course/sis30321-certificate-iii-fitness-sis30321',
    updated_at = NOW()
WHERE cricos_course_code = '107364E';
UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications are open for 2026. <br/><strong>Online Application: </strong>This course is available for online application. <br/><strong>Apprenticeships/Traineeships: </strong>This course can be undertaken as a traineeship. Visit <a href="https://www.cdu.edu.au/tafe/apprenticeships-traineeships">TAFE Apprenticeships and Traineeships</a> for more information. (example)</p><p>This qualification reflects the role of personal trainers who develop, instruct and evaluate personalised exercise programs for generally healthy and low risk clients, to achieve specific fitness goals. Clients with higher health risks are referred to medical or allied health professionals.</p><p>Personal trainers work independently using highly developed fitness skills and knowledge in both routine and unpredictable situations. They use well-developed communication and collaboration skills to interact with clients and health professionals to improve client fitness outcomes.</p><p>The skills in this qualification must be applied in accordance with Commonwealth and State or Territory legislation, Australian standards, and industry codes of practice.</p><p>No occupational licensing, certification, or specific legislative requirements apply to this qualification at the time of publication.</p><p><strong>Classes </strong><br/>Wednesday<br/>10:00am to 4:00pm<br/>Thursday<br/>9:00am to 3:00pm</p><p><strong>Tutorial/Drop In Session:</strong><br/>Tuesday<br/>3:00pm to 5:00pm</p><p>Possible job titles relevant to this qualification include:</p>',
    course_duration_per_week = 26,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals.</p><p>To gain entry into SIS40221 Certificate IV in Fitness, candidates require:</p><ul><li>To have access to a Fitness facility supervised by qualified trainers (paid or volunteer)</li><li>To hold or must be eligible for a Working with Children Clearance (also known as Ochre card)</li></ul><p>Entry to this qualification is open to individuals who hold the following units of competency or units that have been superseded and are equivalent to these units:</p><ul><li>HLTAID011 Provide First Aid (or a unit that supersedes this unit)</li><li>HLTWHS001 Participate in workplace health and safety</li><li>SISFFIT032 Complete pre-exercise screening and service orientation</li><li>SISFFIT033 Complete client fitness assessments</li><li>SISFFIT035 Plan group exercise sessions</li><li>SISFFIT036 Instruct group exercise sessions</li><li>SISFFIT040 Develop and instruct gym-based exercise programs for individual clients</li><li>SISFFIT047 Use anatomy and physiology knowledge to support safe and effective exercise</li><li>SISFFIT052 Provide healthy eating information</li></ul><p>The people-first approach to flexibility and supportive learning environment at CDU meant I could find a balance with study, work and family life.</p><p> CDU student </p><p>Charles Darwin University is a platform that can serve as a bridge for your future. Australia is a land of opportunities and when you work hard you get to see the fruits of your labour.</p><p> CDU student </p><p>The people-first approach to flexibility and supportive learning environment at CDU meant I could find a balance with study, work and family life.</p><p> CDU student </p><p>Charles Darwin University is a platform that can serve as a bridge for your future. Australia is a land of opportunities and when you work hard you get to see the fruits of your labour.</p>',
    apply_form = 'https://www.cdu.edu.au/study/course/sis40221-certificate-iv-fitness-sis40221',
    updated_at = NOW()
WHERE cricos_course_code = '109632G';
-- ⏭️ (no CRICOS): SIT10122 Certificate I in Tourism (Australian Indigenous Culture) | https://www.cdu.edu.au/study/course/sit10122-certificate-i-tourism-australian-indigenous-culture-sit10122

UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications are open for 2026. <br/><strong>Online Application: </strong>This course is available for online application. <br/><strong>Apprenticeships/Traineeships: </strong>This course can be undertaken as a traineeship. Visit <a href="https://www.cdu.edu.au/tafe/apprenticeships-traineeships">TAFE Apprenticeships and Traineeships</a> for more information.</p><p>This qualification reflects the role of individuals who use a range of well-developed tourism service, sales or operational skills and sound knowledge of industry operations to coordinate tourism services. Using discretion and judgement, they work with some independence and under limited supervision using plans, policies and procedures to guide work activities.</p><p>This qualification provides a pathway to work in many tourism industry sectors and for a diversity of employers including tour operators, inbound tour operators, visitor information centres, attractions, cultural and heritage sites, and any small tourism business.</p><p>This qualification allows for multi-skilling and for specialisation in office-based roles involving the planning and coordination of tourism services, in roles in the field where products are delivered or in performing operational activities such as housekeeping, grounds maintenance and providing customer service.</p><p>The skills in this qualification must be applied in accordance with Commonwealth and State/Territory legislation, Australian standards and industry codes of practice.</p><p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p><p>1 year full-time<br/>2 years part-time</p><p>*Duration may vary depending on how long a student takes to reach the required competency level</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>There are no formal entry requirements for this qualification. A pre-enrolment induction will be conducted, and students will be required to complete a learner support indicator to determine any learner support requirements.</p><p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals.</p><p><strong>Required Resources</strong></p><p>Students will have 24/7 access to assessments and learning resources on Learnline, CDU''s online learning platform. Before you can start using Learnline, you''ll need to make sure that your computer has the correct setup. For more details: <a href="https://www.cdu.edu.au/current-students/services/learnline">Learnline | Charles Darwin University</a>.</p><p>Computer and internet access is required to source information and complete assessments.</p><p>I wanted to turn my regular job into my dream job, and the Charles Darwin University course offered exactly what I needed: practical skills.</p><p> CDU student </p><p>CDU graduates have the best career and employment prospects. International students have ranked CDU 1st in Australia for learning and living experience</p><p> CDU student </p><p>I wanted to turn my regular job into my dream job, and the Charles Darwin University course offered exactly what I needed: practical skills.</p><p> CDU student </p><p>CDU graduates have the best career and employment prospects. International students have ranked CDU 1st in Australia for learning and living experience</p>',
    apply_form = 'https://www.cdu.edu.au/study/course/sit30125-certificate-iii-tourism-sit30125',
    updated_at = NOW()
WHERE cricos_course_code = '107364E';
UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications are open for 2026. <br/><strong>Online Application: </strong>This course is available for online application. <br/><strong>Apprenticeships/Traineeships: </strong>This course can be undertaken as a traineeship. Visit <a href="https://www.cdu.edu.au/tafe/apprenticeships-traineeships">TAFE Apprenticeships and Traineeships</a> for more information. </p><p>This qualification reflects the role of individuals who have a range of well-developed hospitality service, sales or operational skills and sound knowledge of industry operations. Using discretion and judgement, they work with some independence and under supervision using plans, policies and procedures to guide work activities. <br/>This qualification provides a pathway to work in organisations such as restaurants, hotels, motels, clubs, pubs, cafés, and coffee shops. This qualification allows for multiskilling and for specialisation in accommodation services, food and beverage and gaming. <br/>The skills in this qualification must be applied in accordance with Commonwealth and State/Territory legislation, Australian standards and industry codes of practice. <br/>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication. </p><p>Possible occupations relevant to this qualification include:</p><ul><li>Senior bar attendant</li><li>Expresso coffee machine operator</li><li>Food and beverage attendant</li><li>Function attendant</li><li>Function host</li><li>Restaurant host</li><li>Waiter</li><li>Wine waiter</li></ul><p><strong>Recognition of Prior Learning (RPL)</strong><br/><br/> RPL is the acknowledgement of a person''s skills and knowledge acquired through previous training, work or life experience, which may be used to grant status or credit in a subject regardless of how and where they were attained, including overseas.This can include skills from:</p><ul><li>Previous study excluding courses at another VET/TAFE institution, but including courses at school or college, through adult education classes or training programs at work;</li><li>Work experience (including both work that is paid and unpaid); and/or</li><li>Life experience (for example leisure pursuits or voluntary work).</li></ul><p>RPL is a form of assessment. It is used to determine whether a person has acquired, through formal or informal learning, the skills and experience consistent with the stated competency standards that comprise a qualification. RPL is <strong>not time referenced</strong>, so there are no parameters on how or when the skills are acquired. However, the skills that have been acquired through life experience etc., must be current and must match the elements and performance criteria contained in the individual unit.<br/><br/> Students seeking RPL need to indicate this on their enrolment form at the time of enrolment.<br/><br/> For further information please refer to the <a href="http://www.cdu.edu.au/course-docs/ApplicantsGuidetoRPLv1.6.pdf">Applicant''s Guide to the Recognition of Prior Learning</a> or contact Student Central on <strong>1800 061 963</strong> (free call) or email <a href="mailto:Student.Central@cdu.edu.au">Student.Central@cdu.edu.au</a>.</p><p><strong>Credit Transfer</strong><br/><br/> Charles Darwin University as a Registered Training Organisation recognises the Australian Qualifications Framework qualifications and Statement of Attainments issued by any other Australian Registered Training Organisation.<br/><br/> Students are encouraged to submit any requests for credit from previous studies at the time of enrolment, to ensure they are not enrolling in units they may not need to undertake.<br/><br/> In order to apply for exemption/credit transfer from units completed at another training organisation, you will need to complete an <a href="http://www.cdu.edu.au/files/2023-03/tafe110-application-for-credit-transfer.pdf">Application for Exemption Form</a> available from any campus, centre, or team, or a copy of the form can be obtained from the web.<br/><br/> Your completed Application for Exemption form together with attached documentary evidence (certified copy of Qualification/Statement of Attainment) to support your request for exemption/credit transfer should be submitted directly to the University either in person or by mail. Requests without documentary evidence will not be processed and will be returned to students. There are no fees attached to Credit Transfers.</p>',
    course_duration_per_week = 26,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals.</p><p>To gain entry into SIT30622 Certificate III in Hospitality, candidates: </p><ul><li>Must be 18 years or age or above</li><li>Are expected to be working within the local hospitality industry in an environment where they have the opportunity to practice the skills required</li></ul><p>I wanted to turn my regular job into my dream job, and the Charles Darwin University course offered exactly what I needed: practical skills.</p><p> CDU student </p><p>CDU graduates have the best career and employment prospects. International students have ranked CDU 1st in Australia for learning and living experience</p><p> CDU student </p><p>I wanted to turn my regular job into my dream job, and the Charles Darwin University course offered exactly what I needed: practical skills.</p><p> CDU student </p><p>CDU graduates have the best career and employment prospects. International students have ranked CDU 1st in Australia for learning and living experience</p><p> CDU student </p><p>This is a current, nationally accredited qualification from the SIT - Tourism, Travel and Hospitality Training Package.</p>',
    apply_form = 'https://www.cdu.edu.au/study/course/sit30622-certificate-iii-hospitality-sit30622',
    updated_at = NOW()
WHERE cricos_course_code = '107364E';
-- ⏭️ (no CRICOS): SIT30821 Certificate III in Commercial Cookery | https://www.cdu.edu.au/study/course/sit30821-certificate-iii-commercial-cookery-sit30821

UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications are open for 2026.<br/><strong>International Availability: </strong>This course is available to International students. Please refer to <a href="https://www.cdu.edu.au/international">International</a> for course and fee information.<br/><strong>Online Application: </strong>To be confirmed. Please contact the team on the details below for further information on how to apply. <br/><strong>Apprenticeships/Traineeships: </strong>Currently not available as either an apprenticeship or traineeship.</p><p>This qualification reflects the role of chefs and cooks who have a supervisory or team leading role in the kitchen. They operate independently or with limited guidance from others and use discretion to solve non-routine problems.</p><p>This qualification provides a pathway to work in organisations such as restaurants, hotels, clubs, pubs, cafes and coffee shops, or to run a small business in these sectors.</p><p>The skills in this qualification must be applied in accordance with Commonwealth and State or Territory legislation, Australian standards and industry codes of practice.</p><p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p><p>Domestic<br/>1.5 years full-time<br/>3 years part-time</p><p>International<br/>1.5 years full-time<br/>*Duration may vary depending on how long a student takes to reach the required competency level</p><p>Possible occupations relevant to this qualification include:</p>',
    course_duration_per_week = 78,
    offshore_tuition_fee = 34840,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>While there is no qualification entry requirement, students will be expected to have employment in a relevant position in a commercial kitchen to satisfy the requirements of core unit SITHCCC043 Work effectively as a cook which requires students to complete 48 restaurant services. <br/><br/>Students must wear work clothing suited to the industry. The Training Restaurant is a simulated work environment, therefore closed-in shoes with non-slip soles are compulsory. Refer to the Resources section for a list of uniform and tools required to undertake this qualification.</p><p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals.</p><p><strong>Required Resources</strong><br/>Students will have 24/7 access to assessments and learning resources on CDU''s online learning platform, Learnline. Before using Learnline howeve, students will need to ensure that their computer has the correct <a href="https://www.cdu.edu.au/current-students/services/learnline">setup</a>. </p><p>Students are issued wit the required learning and assessment materials for each unit.</p><p><strong>Uniform</strong><br/>A complete, clean, laundered and ironed uniform, and correct footwear must always be worn while attending class.</p><p>Uniform requirements for practical classes:</p><ul><li>2 x White double breasted Chefs jacket (Not black. Complete with white buttons)</li><li>2 x Chefs trousers (Not black. Checked - modern or traditional)</li><li>2 x White apron</li><li>2 x Navy blue neckerchief</li><li>1 x White Chef''s hat (skull cap)</li><li>1 x Shoes - heavy duty, non-slip and clean (no sneakers or runners)</li><li>2 x Long sleeve white button business shirt</li><li>2 x Black trousers/skirt (below the knee in length)</li><li>1 x Shoes - formal black lace up (no sneakers, runners or heavy-duty boots)</li></ul><p><strong>Tools of Trade</strong><br/>Students will be required to supply their own tools of trade which includes cook''s knives to use. All tools, uniforms and other equipment must be clearly identified by engraving or pen.</p><p>Starter toolkit:</p><ul><li>1 x 25cm/30cm Chef''s knife</li><li>1 x Steel</li><li>1 x Paring knife</li><li>1 x Vegetable peeler</li><li>1 x Thermometer</li><li>1 x Palette knife</li><li>1 x Boning knife</li><li>1 x Fish filleting knife</li><li>1 x Utility fork</li><li>1 x Thermal piping bag</li><li>1 x Set nozzles</li><li>1 x Sharpening stone</li></ul><p>As part of the application process, it is important that you meet the minimum academic entry requirements. If you have any questions, please email the <a href="https://international@cdu.edu.au">International team</a>: international@cdu.edu.au. We look forward to helping you through the process of applying to study with us at CDU.</p><p>The minimum English language requirement for this course is met by either undertaking previous education from an <a href="http://www.cdu.edu.au/international/how-apply/entry-requirements">English-speaking country</a> or undertaking one of the following English language tests and obtaining the minimum requirements listed below.</p>',
    apply_form = 'https://www.cdu.edu.au/study/course/sit40521-certificate-iv-kitchen-management-sit40521',
    updated_at = NOW()
WHERE cricos_course_code = '109632G';
UPDATE courses SET
    course_description = '<p><strong>Availability: </strong>Applications are open for 2026. <br/><strong>International Availability: </strong>This course is available to International students. <br/><strong>Online Application: </strong>This course is available for online applications. <br/><strong>Apprenticeships/Traineeships: </strong>This course can be undertaken as a traineeship. Visit <a href="https://www.cdu.edu.au/tafe/apprenticeships-traineeships">TAFE Apprenticeships and Traineeships</a> for more information. <br/></p><p>This qualification provides the skills and knowledge for a person to be competent in skilled operations, and team leading or supervision. Work is undertaken in various hospitality settings such as restaurants, hotels, motels, clubs, pubs, cafes and coffee shops. The qualification is suitable for an apprenticeship pathway. Studies can be undertaken either on campus or externally at the workplace, with exception of some units which require face to face training. <br/>The program is designed to give students flexible training options. There is a combination of on-campus and work experience training. On-campus training includes a range of practical activities in a simulated work environment <br/>This qualification is available to international students (CRICOS Course No. 112161G). Please refer to <a href="https://www.cdu.edu.au/international">CDU International</a> for the course and fee information.</p><p>Possible occupations relevant to this qualification include:</p><ul><li>Hospitality Manager</li><li>Hotel Manager</li><li>Restaurant Manager</li><li>Sous Chef</li><li>Chef Patissier</li></ul><p><strong>Recognition of Prior Learning (RPL)</strong><br/><br/> RPL is the acknowledgement of a person''s skills and knowledge acquired through previous training, work or life experience, which may be used to grant status or credit in a subject regardless of how and where they were attained, including overseas.This can include skills from:</p><ul><li>Previous study excluding courses at another VET/TAFE institution, but including courses at school or college, through adult education classes or training programs at work;</li><li>Work experience (including both work that is paid and unpaid); and/or</li><li>Life experience (for example leisure pursuits or voluntary work).</li></ul><p>RPL is a form of assessment. It is used to determine whether a person has acquired, through formal or informal learning, the skills and experience consistent with the stated competency standards that comprise a qualification. RPL is <strong>not time referenced</strong>, so there are no parameters on how or when the skills are acquired. However, the skills that have been acquired through life experience etc., must be current and must match the elements and performance criteria contained in the individual unit.<br/><br/> Students seeking RPL need to indicate this on their enrolment form at the time of enrolment.<br/><br/> For further information please refer to the <a href="http://www.cdu.edu.au/course-docs/ApplicantsGuidetoRPLv1.6.pdf">Applicant''s Guide to the Recognition of Prior Learning</a> or contact Student Central on <strong>1800 061 963</strong> (free call) or email <a href="mailto:Student.Central@cdu.edu.au">Student.Central@cdu.edu.au</a>.</p><p><strong>Credit Transfer</strong><br/><br/> Charles Darwin University as a Registered Training Organisation recognises the Australian Qualifications Framework qualifications and Statement of Attainments issued by any other Australian Registered Training Organisation.<br/><br/> Students are encouraged to submit any requests for credit from previous studies at the time of enrolment, to ensure they are not enrolling in units they may not need to undertake.<br/><br/> In order to apply for exemption/credit transfer from units completed at another training organisation, you will need to complete an <a href="http://www.cdu.edu.au/files/2023-03/tafe110-application-for-credit-transfer.pdf">Application for Exemption Form</a> available from any campus, centre, or team, or a copy of the form can be obtained from the web.<br/><br/> Your completed Application for Exemption form together with attached documentary evidence (certified copy of Qualification/Statement of Attainment) to support your request for exemption/credit transfer should be submitted directly to the University either in person or by mail. Requests without documentary evidence will not be processed and will be returned to students. There are no fees attached to Credit Transfers.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 34840,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals.</p><p>To gain entry into SIT50422 Diploma of Hospitality Management, candidates are required:</p><ul><li>To either undertake SIT30622 Certificate III in Hospitality or SIT40422 Certificate IV in Hospitality</li></ul><p><strong>OR</strong></p><ul><li>To be currently working in the industry prior to commencing the SIT50422 Diploma of Hospitality</li></ul><p><strong>Required Resources</strong></p><p>Students will have 24/7 access to assessments and learning resources on CDU''s online learning platform Learnline. Before you can use Learnline however, you''ll need to ensure that your computer has the correct <a href="https://www.cdu.edu.au/current-students/services/learnline">setup</a>.</p><p>Computer and internet access may be required to source information and complete assessments.</p><p><strong>Uniform </strong><br/>Complete clean, laundered and ironed business attire, and correct footwear must be worn at all times while attending class.</p><p>As part of the application process, it is important that you meet the minimum academic entry requirements. If you have any questions, please email the <a href="https://international@cdu.edu.au">International team</a>: international@cdu.edu.au. We look forward to helping you through the process of applying to study with us at CDU.</p><p>The minimum English language requirement for this course is met by either undertaking previous education from an <a href="http://www.cdu.edu.au/international/how-apply/entry-requirements">English-speaking country</a> or undertaking one of the following English language tests and obtaining the minimum requirements listed below.</p><p>* All tests are valid for two years from the date of the test to the date of commencement at CDU, unless otherwise specified.<br/>* Where applicable, international applicants must also satisfy the <a href="https://immi.homeaffairs.gov.au/">Department of Home Affairs</a> (DHA) English language requirements for student visa applications.</p>',
    apply_form = 'https://www.cdu.edu.au/study/course/sit50422-diploma-hospitality-management-sit50422',
    updated_at = NOW()
WHERE cricos_course_code = '112161G';
